import { ServiceWorkerMessage } from './service-worker-message';
/**
 * There is a message system built into service workers to communicate with the main thread
 * You can attach any type of along with the message
 * This message object contains everything we need when handling PRE_FETCH messages
 * For 'DATA_IN_FLIGHT_WITH_FULL_RESPONSE_OBJECT_RETURNED' Response is returned for error responses and non 200 responses
*/
export interface ServiceWorkerPrefetchMessage extends ServiceWorkerMessage {
    type: 'PRE_FETCH_RESPONSE';
    payload?: TimeStampedPayload | SerializedResponse;
    case: 'DATA_FROM_CACHE' | 'DATA_FROM_IN_FLIGHT_FETCH' | 'NO_DATA_FROM_PRE_FETCH' | 'DATA_IN_FLIGHT_WITH_FULL_RESPONSE_OBJECT_RETURNED';
    prefetchPid: string;
    responseIsStale: boolean;
    isInProgress?: boolean;
}
export interface SerializedResponse {
    headers: Array<[string, string]>;
    status: number;
    statusText: string;
    arrayBufferAsString: string;
}
/**
 * This represents any payload that made a request and was intercepted by our service worker
 */
export interface TimeStampedPayload {
    networkCallTimeStamp: string;
    networkPayload: any;
    cacheTimeStamp?: string;
}
/**
 * When the payload of a response is cached, we add the cacheTimeStamp to it
 * The cacheTimeStamp is used to determine if data is stale or expired
 * This is the type we have after decrypting the payload from the cache
 */
export interface CachedTimeStampedPayload extends TimeStampedPayload {
    cacheTimeStamp: string;
    superFetchTagList?: Array<string>;
}
/**
 * Inside the browser cache (L2 Cache) we must encrypt the data
 * The response stored in the cache has the data we need to decrypt
 * and it has the encrypted network payload stored in it as a string
 */
export interface TimeStampedEncryptedPayload extends CachedTimeStampedPayload {
    encryptionKeyId: string;
    iv: Array<number>;
    networkPayload: string;
    stale: number;
    expires: number;
}
/**
 * This is the payload that we return to developers
 * The "any" is all of the data we received from the call that we know nothing about
 * The other properties are used by superFetch and developers
 */
export type SuperFetchPayload = any & {
    networkCallTimeStamp: string;
    cacheTimeStamp?: string;
};
/**
 * This is the timeout object we set for each url in the service worker
 * This has the data we need from the developer to determine if data is stale or not
 */
export interface CacheTimeoutRecord {
    stale: number;
    expires: number;
    urlRegex: RegExp;
}
export interface EncryptionKeys {
    activeKeyId: string;
    keys: Array<{
        'keyId': string;
        'value': string;
    }>;
}
